  ["quest:abyssea:127"] = {
    objective_name = "Ward Warden II (Attohwa)",
    page = {
      title = "Ward Warden II (Attohwa)",
      page_id = 172778,
      revision_id = 1479941,
      revision_timestamp = "2014-03-05T06:47:43Z",
      content_sha256 = "baa7ecd857748cf7a213617d4df101298a62b761d118ecbea71655c604a46405",
      source_url = "https://ffxiclopedia.fandom.com/wiki/Ward_Warden_II_(Attohwa)",
      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Talk to the Resistance Sapper and accept the quest. He will mark your target area on the map. This is a different crate than the one used in Desert Rain II (Attohwa).",
        action = "talk",
        entities = { "Resistance Sapper", "Desert Rain II (Attohwa)" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "Your objective: Escort the chocobo to the repair crate, load up one or more materials, and escort the chocobo back to the Chocobo Tamer.",
        action = "note",
        entities = { "Chocobo Tamer" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "Speak with Chocobo Tamer at (F-8) to purchase chocobo travel goods with Cruor.",
        action = "talk",
        entities = { "Chocobo Tamer" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "F-8" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "**",
        depth = 2,
        instruction = "Chocobo Blinkers are, for all realistic purposes, required for this quest, unless every monster on the chocobo's path is dead.",
        action = "note",
        entities = { "Chocobo Blinkers" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 5,
        marker = "*",
        depth = 1,
        instruction = "Talk to the Chocobo Tamer again and choose to begin the operation. A chocobo NPC will appear, ready for you to escort it.",
        action = "talk",
        entities = { "Chocobo Tamer" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 6,
        marker = "**",
        depth = 2,
        instruction = "The chocobo may run away if it sees a monster. Bastion monsters will not frighten it. Every other monster will, including non-aggressive ones.",
        action = "note",
        entities = { "Bastion" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 7,
        marker = "***",
        depth = 3,
        instruction = "If you are within a few yalms of the chocobo when it panics, you can click it and it will stop fleeing. It's a good idea to keep the chocobo targeted at all times, to easily stop it if it panics and to use items on it.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 8,
        marker = "***",
        depth = 3,
        instruction = "The chocobo can endure monsters being very close to it, and even in front of it, if it is under the effect of blinkers and you are very close to it. When walking through an area thick with enemies, walk slowly to keep it close. If you get cut off and surrounded, stay immediately next to the chocobo until an opening appears.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 9,
        marker = "**",
        depth = 2,
        instruction = "The chocobo detects by sight, but Chocobo Blinkers can shorten and narrow its area of vision. They do not prevent the chocobo from seeing enemies close to and directly in front of it or impair its ability to follow you.",
        action = "note",
        entities = { "Chocobo Blinkers" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 10,
        marker = "**",
        depth = 2,
        instruction = "Although you cannot interact with the chocobo while under the effect of Invisible, if it is already following you it will continue to follow if you are under the effects of Sneak and/or Invisible. Applying Sneak or Invisible as appropriate to avoid aggro makes these quests far easier.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 11,
        marker = "**",
        depth = 2,
        instruction = "You can talk to the chocobo to make it stop/start walking. You can trade it the items sold by Chocobo Tamers to give special effects. If you get too far ahead, the chocobo will halt in place. The chocobo can almost keep up with a character with movement speed enhancements, and this may be useful in stretches without enemies.",
        action = "note",
        entities = { "Chocobo Tamer" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 12,
        marker = "**",
        depth = 2,
        instruction = "The chocobo will not be attacked; however, it constantly and rather quickly loses HP at all times. Azouph Greens are recommended, and can give you a lot more time to complete the quest.",
        action = "note",
        entities = { "Azouph Greens" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 13,
        marker = "**",
        depth = 2,
        instruction = "Multiple items cannot be affecting your pack chocobo at a given time. For example, if the chocobo is under the effect of Chocobo Blinkers, you cannot use a Speed Apple to boost its speed. Greens can and should be used in conjunction with blinkers, however. Also, feeding a chocobo Gysahl Greens or Azouph Greens will prevent feeding further greens for 90 seconds, because it will be \"full.\"",
        action = "note",
        entities = { "Chocobo Blinkers", "Speed Apple", "Gysahl Greens", "Azouph Greens" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 14,
        marker = "*",
        depth = 1,
        instruction = "Travel to (G-6) and select the larger crate. This area is accessible through the tunnel behind the Inugami, not the tunnel behind the Schnitter.",
        action = "travel",
        entities = { "Inugami", "Schnitter" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "G-6" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 15,
        marker = "*",
        depth = 1,
        instruction = "Load your chocobo and guide it back to the Chocobo Tamer.",
        action = "note",
        entities = { "Chocobo Tamer" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 16,
        marker = "**",
        depth = 2,
        instruction = "This quest is difficult, so if you are only completing it one time for completion's sake load only one material. Materials loaded will reduce the pack chocobo's speed.",
        action = "note",
        entities = {  },
        zones = {  },
