        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 12,
        marker = "**",
        depth = 2,
        instruction = "The Chocobo has a distinct pattern, usually a dash, then a long look away, then a small trot, quickly followed by a turn (don't try during this phase as it always turns as you come up to it then back to the dash, repeated.) It also only walks/runs to 4 locations around the Spoor and will only face particular directions at each spot, using this information it's pattern is easily observed, once you get it, it...",
