        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 13,
        marker = "**",
        depth = 2,
        instruction = "If you approach when it is facing you, it will say, \"Kweh!?\", be spooked, and run off to a new location. The Chocobo may randomly run deep into the Coeurls or chasm tunnels and disappear.",
