        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 14,
        marker = "**",
        depth = 2,
        instruction = "There are two \"levels\" of spooking the chocobo. If you click it while its looking at you, it will say \"Kweeeh Kweeeh!\" and run away, to my experience into the Coeurls.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 15,
        marker = "**",
        depth = 2,
        instruction = "The \"Kweeeh Kweeh\" message is received if you click the chocobo after it is already spooked. if you get the Kweh Kweh message twice before it de-spawns it will stop and go back to the normal area. you can have another chance to finish the quest if it does not see you on the way back.",
